import fs from "node:fs";
import path from "node:path";

const SHOTS = "/private/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/f6fd932e-9474-4440-a15d-a9ef479f86a8/scratchpad/eng2367";
const TAG = "#res-candidate";
const consoleErrors = [];
const log = (...a) => console.log("[eng2367]", ...a);

const closeModals = async (page) => {
  for (let i = 0; i < 6; i++) {
    const open = await page.locator(".bp3-dialog, .bp3-overlay-open").count();
    if (!open) return;
    await page.keyboard.press("Escape");
    await page.waitForTimeout(250);
  }
};

const setup = (page) =>
  page.evaluate(async ({ TAG }) => {
    const api = window.roamAlphaAPI;
    const gen = () => api.util.generateUID();
    const ts = Date.now().toString(36);
    const ids = {};
    const mkPage = async (key, title) => {
      const uid = gen();
      await api.data.page.create({ page: { title, uid } });
      ids[key] = uid;
      return uid;
    };
    const mk = async (parent, order, string, extra = {}) => {
      const uid = gen();
      await api.data.block.create({ location: { "parent-uid": parent, order }, block: { string, uid, ...extra } });
      return uid;
    };
    const A = await mkPage("pageA", `ENG2367 A ${ts}`);
    const B = await mkPage("pageB", `ENG2367 B ${ts}`);
    const C = await mkPage("pageC", `ENG2367 C ${ts}`);
    const H = await mkPage("pageH", `ENG2367 highlight ${ts}`);

    // Page A: embed (filled later), 30 fillers, deep chain, 30 fillers, A-top (+child), 20 fillers
    ids.embed = await mk(A, "last", "placeholder");
    for (let i = 0; i < 30; i++) await mk(A, "last", `filler A1 ${i}`);
    const l1 = await mk(A, "last", "A level 1", { open: true });
    const l2 = await mk(l1, "last", "A level 2", { open: true });
    const l3 = await mk(l2, "last", "A level 3", { open: true });
    ids.aDeep = await mk(l3, "last", `ENG2367 A-deep ${TAG}`);
    ids.aDeepAncestors = [l1, l2, l3];
    for (let i = 0; i < 30; i++) await mk(A, "last", `filler A2 ${i}`);
    ids.aTop = await mk(A, "last", `ENG2367 A-top ${TAG}`, { open: true });
    ids.aTopChild = await mk(ids.aTop, "last", "A-top child block");
    for (let i = 0; i < 20; i++) await mk(A, "last", `filler A3 ${i}`);
    await api.data.block.update({ block: { uid: ids.embed, string: `{{embed: ((${ids.aTop}))}}` } });

    // Page B
    for (let i = 0; i < 5; i++) await mk(B, "last", `filler B ${i}`);
    ids.bParent = await mk(B, "last", "B collapsed parent");
    ids.bCollapsed = await mk(ids.bParent, "last", `ENG2367 B-collapsed ${TAG}`);
    ids.bGrand = await mk(B, "last", "B collapsed grandparent");
    ids.bGrandParent = await mk(ids.bGrand, "last", "B open parent", { open: true });
    ids.bGrandChild = await mk(ids.bGrandParent, "last", `ENG2367 B-grand ${TAG}`);
    await api.data.block.update({ block: { uid: ids.bParent, open: false } });
    await api.data.block.update({ block: { uid: ids.bGrand, open: false } });

    // Page C: fillers, big image, fillers, C-short, fillers
    for (let i = 0; i < 20; i++) await mk(C, "last", `filler C1 ${i}`);
    ids.img = await mk(C, "last", `![](https://picsum.photos/id/1018/800/1200?eng2367=${ts})`);
    for (let i = 0; i < 3; i++) await mk(C, "last", `filler C2 ${i}`);
    ids.cShort = await mk(C, "last", `ENG2367 C-short ${TAG}`);
    for (let i = 0; i < 8; i++) await mk(C, "last", `filler C3 ${i}`);

    ids.hl = await mk(H, "last", "^^x^^");

    // Regular Claim node page, using the Claim format from settings.
    const claimProps = api.pull("[:block/props]", [":node/title", "discourse-graph/nodes/Claim"])?.[":block/props"] || {};
    const fmt = claimProps[":format"] || "[[CLM]] - {content}";
    ids.regularTitle = fmt.replace("{content}", `ENG2367 regular ${ts}`);
    await mkPage("regular", ids.regularTitle);
    await mk(ids.regular, "last", "regular node body");
    ids.ts = ts;
    return ids;
  }, { TAG });

const openState = (page, uids) =>
  page.evaluate((uids) => {
    const r = {};
    for (const u of uids) r[u] = window.roamAlphaAPI.pull("[:block/open]", [":block/uid", u])?.[":block/open"];
    return r;
  }, uids);

const facts = (page) =>
  page.evaluate(() => {
    const dialog = document.querySelector(".bp3-dialog");
    const container = dialog?.querySelector(".overflow-y-auto.border-t");
    const cRect = container?.getBoundingClientRect();
    const flashed = Array.from(document.querySelectorAll(".dg-search-preview-flash")).map((el) => {
      const r = el.getBoundingClientRect();
      return {
        cls: el.className.slice(0, 80),
        blockUid: el.closest(".rm-block")?.getAttribute("data-block-uid"),
        text: el.textContent.slice(0, 60),
        inEmbed: !!el.closest(".rm-embed-container"),
        inDialog: !!el.closest(".bp3-dialog"),
        rowTopInContainer: cRect ? Math.round(r.top - cRect.top) : null,
        rowHeight: Math.round(r.height),
        centreOffset: cRect ? Math.round(r.top + r.height / 2 - (cRect.top + cRect.height / 2)) : null,
        bg: getComputedStyle(el).backgroundColor,
      };
    });
    const active = dialog?.querySelector('[role="option"][aria-selected="true"]');
    const main = document.querySelector(".roam-body-main");
    const art = document.querySelector(".rm-article-wrapper");
    const scrollers = Array.from(document.querySelectorAll("body *")).filter((e) => !e.closest(".bp3-portal") && e.scrollHeight > e.clientHeight + 20 && /(auto|scroll)/.test(getComputedStyle(e).overflowY)).map((e) => ({ sel: e.tagName.toLowerCase() + (e.id ? "#" + e.id : "") + "." + String(e.className).split(" ").slice(0, 2).join("."), top: Math.round(e.scrollTop) }));
    return {
      flashed,
      activeText: active?.textContent?.slice(0, 80),
      container: container && {
        scrollTop: Math.round(container.scrollTop),
        scrollHeight: container.scrollHeight,
        clientHeight: container.clientHeight,
        zoomPath: !!container.querySelector(".rm-zoom-path"),
        pageTitle: container.querySelector(".rm-title-display, h1")?.textContent?.slice(0, 60) || null,
        blockCount: container.querySelectorAll(".rm-block[data-block-uid]").length,
        mountCount: container.querySelector(".pointer-events-none > div")?.children.length,
        imgs: Array.from(container.querySelectorAll("img")).map((i) => ({ complete: i.complete, h: i.naturalHeight })),
      },
      mainScroll: { roamBodyMain: main?.scrollTop, articleWrapper: art?.scrollTop, windowY: window.scrollY, scrollers },
    };
  });

const waitFlash = async (page, ms = 4000) => {
  try {
    await page.waitForFunction(() => document.querySelector(".dg-search-preview-flash"), null, { timeout: ms });
    return true;
  } catch {
    return false;
  }
};

const shot = async (page, name) => {
  const p = path.join(SHOTS, `${name}.png`);
  await page.screenshot({ path: p });
  return p;
};

const rows = (page) => page.locator('.bp3-dialog [role="listbox"] [role="option"]');
const rowIndex = async (page, needle) => {
  const texts = await rows(page).allTextContents();
  return texts.findIndex((t) => t.includes(needle));
};
const activeIndex = async (page) =>
  page.evaluate(() =>
    Array.from(document.querySelectorAll('.bp3-dialog [role="option"]')).findIndex((e) => e.getAttribute("aria-selected") === "true"),
  );
const moveTo = async (page, needle) => {
  const target = await rowIndex(page, needle);
  if (target < 0) throw new Error(`row not found: ${needle}`);
  let cur = await activeIndex(page);
  while (cur !== target) {
    await page.keyboard.press(cur < target ? "ArrowDown" : "ArrowUp");
    cur += cur < target ? 1 : -1;
  }
};

const openSearch = async (page, term) => {
  await page.evaluate(() => window.__dgPlaywrightCommandCallbacks?.["DG: Open Node Search"]?.());
  let ok = await page.locator(".bp3-dialog [role='listbox'], .bp3-dialog input").first().waitFor({ timeout: 4000 }).then(() => true, () => false);
  if (!ok) {
    // Fallback: Roam command palette.
    await page.keyboard.press("Meta+p");
    await page.waitForTimeout(500);
    await page.keyboard.type("DG: Open Node Search");
    await page.waitForTimeout(800);
    await page.keyboard.press("Enter");
    await page.locator(".bp3-dialog input").first().waitFor({ timeout: 8000 });
  }
  await page.locator('.bp3-dialog button[aria-label="Display options"]').click();
  await page.getByText("Show candidate nodes").click();
  await page.waitForTimeout(300);
  await page.locator('.bp3-dialog button[aria-label="Display options"]').click();
  await page.waitForTimeout(300);
  const input = page.locator(".bp3-dialog input[type='text'], .bp3-dialog input:not([type])").first();
  await input.click();
  await input.fill(term);
  await page.waitForFunction(() => document.querySelectorAll('.bp3-dialog [role="option"]').length >= 6, null, { timeout: 20000 });
  await page.waitForTimeout(1200);
  // Park the mouse away from the list so hover can't steal the selection.
  await page.mouse.move(5, 5);
};

export default {
  async ready({ page }) {
    await closeModals(page);
    return true;
  },
  async run({ page }) {
    page.on("console", (m) => {
      if (m.type() === "error") consoleErrors.push(m.text().slice(0, 300));
    });
    page.on("pageerror", (e) => consoleErrors.push("pageerror: " + e.message.slice(0, 300)));
    await page.setViewportSize({ width: 1440, height: 900 }).catch(() => {});
    const out = { flag: null, scenarios: {} };
    out.flag = await page.evaluate(() => Object.keys(window.__dgPlaywrightCommandCallbacks || {}));
    const ids = await setup(page);
    out.ids = ids;
    fs.writeFileSync(path.join(SHOTS, "ids.json"), JSON.stringify(ids, null, 2));
    const collapsedAncestors = [ids.bParent, ids.bGrand, ids.bGrandParent];
    out.openBefore = await openState(page, collapsedAncestors);
    await page.waitForTimeout(1500);

    // Highlight colour
    await page.evaluate((uid) => window.roamAlphaAPI.ui.mainWindow.openPage({ page: { uid } }), ids.pageH);
    await page.waitForSelector(".rm-highlight", { timeout: 10000 }).catch(() => {});
    out.highlight = await page.evaluate(() => {
      const el = document.querySelector(".rm-highlight");
      return el ? getComputedStyle(el).backgroundColor : null;
    });
    await page.evaluate(() => window.roamAlphaAPI.ui.mainWindow.openDailyNotes());
    await page.waitForTimeout(800);

    const term = `ENG2367`;
    await openSearch(page, term);
    out.rowTexts = await rows(page).allTextContents();

    // 1. A-top by click
    const s = out.scenarios;
    await rows(page).nth(await rowIndex(page, "A-top")).click();
    s.s1_flashSeen = await waitFlash(page);
    await page.waitForTimeout(400);
    s.s1 = await facts(page);
    s.s1.shot = await shot(page, "s1-a-top");

    // 6 + 2. mark rendered page, then keyboard to A-deep
    s.s6_marked = await page.evaluate(() => {
      const c = document.querySelector(".bp3-dialog .overflow-y-auto.border-t .pointer-events-none > div > div");
      const target = c?.querySelector(".rm-block");
      if (!target) return false;
      target.setAttribute("data-eng2367-marker", "1");
      return true;
    });
    await page.mouse.move(5, 5);
    await page.waitForTimeout(3200); // let A-top flash end
    await page.locator(".bp3-dialog input").first().focus();
    await moveTo(page, "A-deep");
    s.s2_flashSeen = await waitFlash(page);
    await page.waitForTimeout(400);
    s.s2 = await facts(page);
    s.s6_markerSurvived = await page.evaluate(() => !!document.querySelector(".bp3-dialog [data-eng2367-marker]"));
    s.s2.shot = await shot(page, "s2-a-deep");

    // 3. B-collapsed and B-grand
    for (const [key, needle] of [["s3_collapsed", "B-collapsed"], ["s3_grand", "B-grand"]]) {
      await page.waitForTimeout(500);
      await moveTo(page, needle);
      s[key + "_flashSeen"] = await waitFlash(page);
      await page.waitForTimeout(400);
      s[key] = await facts(page);
      s[key].shot = await shot(page, `s3-${needle}`);
    }
    out.openAfterS3 = await openState(page, collapsedAncestors);

    // 7. C-short (image above)
    await moveTo(page, "C-short");
    s.s7_flashSeen = await waitFlash(page);
    await page.waitForTimeout(400);
    s.s7 = await facts(page);
    s.s7.shot = await shot(page, "s7-c-short");
    await page.waitForTimeout(1500);
    s.s7_late = await facts(page);

    // 8. regular node
    await moveTo(page, "regular");
    await page.waitForTimeout(2500);
    s.s8 = await facts(page);
    s.s8.renderedPage = await page.evaluate(() => {
      const c = document.querySelector(".bp3-dialog .overflow-y-auto.border-t");
      return { pageRender: !!c.querySelector(".rm-api-render--page, .roam-article, .rm-title-display"), html: c.innerHTML.slice(0, 300) };
    });
    s.s8.shot = await shot(page, "s8-regular");

    // 5. race: keyboard repeat across candidates
    await page.waitForTimeout(3200);
    const startIdx = await rowIndex(page, "A-top");
    await moveTo(page, "A-top");
    const n = (await rows(page).count()) - 1;
    const D = "ArrowDown", U = "ArrowUp";
    const seq = [D, D, D, U, U, U, U, D, D, D, D, U, U, U, D, U, D, D, D, U, U, U]; // 1->4->0->4->1->2->1->4->1
    await page.evaluate(() => {
      window.__eng2367 = { max: 0, adds: [] };
      const obs = new MutationObserver(() => {
        const n = document.querySelectorAll(".dg-search-preview-flash").length;
        window.__eng2367.max = Math.max(window.__eng2367.max, n);
      });
      obs.observe(document.body, { subtree: true, attributes: true, attributeFilter: ["class"], childList: true });
      window.__eng2367.obs = obs;
    });
    for (const k of seq) {
      await page.keyboard.press(k);
      await page.waitForTimeout(20);
    }
    await page.waitForTimeout(1500);
    s.s5_keys = await facts(page);
    s.s5_keys.shot = await shot(page, "s5-race-keys");
    // hover sweep
    await page.waitForTimeout(3200);
    const box = await page.locator('.bp3-dialog [role="listbox"]').boundingBox();
    const ys = [];
    for (let y = box.y + 5; y < box.y + box.height - 5; y += 12) ys.push(y);
    for (const y of [...ys, ...ys.slice().reverse(), ...ys.slice(0, Math.floor(ys.length / 2))]) {
      await page.mouse.move(box.x + 40, y);
      await page.waitForTimeout(15);
    }
    // End the sweep on the C-short row (index 4) via small steps.
    const target = await rows(page).nth(4).boundingBox();
    for (let y = box.y + 5; y <= target.y + target.height / 2; y += 6) {
      await page.mouse.move(box.x + 60, y);
      await page.waitForTimeout(10);
    }
    await page.waitForTimeout(1500);
    s.s5_hover = await facts(page);
    s.s5_hover.shot = await shot(page, "s5-race-hover");
    s.s5_maxSimultaneousFlash = await page.evaluate(() => { window.__eng2367.obs.disconnect(); return window.__eng2367.max; });
    s.s5_meta = { startIdx, n, rowsTexts: await rows(page).allTextContents() };

    // 4. main window shows page A
    await page.mouse.move(5, 5);
    await closeModals(page);
    await page.evaluate((uid) => window.roamAlphaAPI.ui.mainWindow.openPage({ page: { uid } }), ids.pageA);
    await page.waitForTimeout(2000);
    await page.evaluate(() => {
      const blk = document.querySelector(".roam-body-main .rm-block");
      let el = blk;
      while (el && !(el.scrollHeight > el.clientHeight + 20 && /(auto|scroll)/.test(getComputedStyle(el).overflowY))) el = el.parentElement;
      if (el) { el.scrollTop = 400; el.setAttribute("data-eng2367-main-scroller", "1"); }
    });
    await page.waitForTimeout(500);
    s.s4_mainBefore = await facts(page).then((f) => f.mainScroll);
    s.s4_mainScrollerBefore = await page.evaluate(() => { const e = document.querySelector("[data-eng2367-main-scroller]"); return e ? { cls: e.className, top: e.scrollTop } : null; });
    await openSearch(page, term);
    await page.waitForTimeout(3200);
    s.s4_mainAfterOpen = await facts(page).then((f) => f.mainScroll);
    await moveTo(page, "A-top");
    s.s4_flashSeen = await waitFlash(page);
    await page.waitForTimeout(400);
    s.s4 = await facts(page);
    s.s4.mainScrollerTop = await page.evaluate(() => document.querySelector("[data-eng2367-main-scroller]")?.scrollTop ?? null);
    s.s4.mainTopCopies = await page.evaluate((uid) => document.querySelectorAll(`.roam-body-main .rm-block[data-block-uid="${uid}"]`).length, ids.aTop);
    s.s4.shot = await shot(page, "s4-main-window");
    await closeModals(page);
    out.consoleErrors = consoleErrors;
    return out;
  },
  async cleanup({ page }) {
    let ids;
    try {
      ids = JSON.parse(fs.readFileSync(path.join(SHOTS, "ids.json"), "utf8"));
    } catch {
      return { deleted: [] };
    }
    await closeModals(page);
    return page.evaluate(async (ids) => {
      const api = window.roamAlphaAPI;
      await api.ui.mainWindow.openDailyNotes();
      const deleted = [];
      for (const k of ["pageA", "pageB", "pageC", "pageH", "regular"]) {
        if (!ids[k]) continue;
        await api.data.page.delete({ page: { uid: ids[k] } });
        deleted.push(k);
      }
      const left = api.data.fast.q(`[:find ?t :where [?p :node/title ?t] [(clojure.string/includes? ?t "${ids.ts}")]]`);
      return { deleted, remainingWithTs: left };
    }, ids);
  },
};
